14. Describe the Adapter Pattern and provide an Example of where it can be applied.The Adapter pattern allows the interface of an existing class to be used as another interface. It is often used to make existing classes work with others without modifying their source code. Use the Adapter Pattern when:We need to integrate classes that have incompatible interfaces.We cannot modify the existing class but need it to work with new code or libraries.Example
            C++

    #include <iostream>
using namespace std;

// Target Interface
class ITarget {
public:
    virtual void Request() = 0; // pure virtual function
    virtual ~ITarget() {}       // virtual destructor
};

// Adaptee Class
class Adaptee {
public:
    void SpecificRequest() {
        cout << "Adaptee's method called" << endl;
    }
};

// Adapter Class
class Adapter : public ITarget {
private:
    Adaptee* adaptee;
public:
    Adapter() {
        adaptee = new Adaptee();
    }

    ~Adapter() {
        delete adaptee;
    }

    void Request() override {
        adaptee->SpecificRequest();
    }
};

// Client Code
int main() {
    ITarget* target = new Adapter();
    target->Request(); // Calls adaptee's method through adapter
    delete target;
    return 0;
}


            Java

    import java.util.logging.Logger;

// Target Interface
interface ITarget {
    void Request();
}

// Adaptee Class
class Adaptee {
    public void SpecificRequest() {
        System.out.println("Adaptee's method called");
    }
}

// Adapter Class
class Adapter implements ITarget {
    private Adaptee adaptee;

    public Adapter() {
        adaptee = new Adaptee();
    }

    @Override
    public void Request() {
        adaptee.SpecificRequest();
    }
}

// Client Code
public class Main {
    public static void main(String[] args) {
        ITarget target = new Adapter();
        target.Request(); // Calls adaptee's method through adapter
    }
}


            Python

    import logging

# Target Interface
class ITarget:
    def Request(self):
        pass

# Adaptee Class
class Adaptee:
    def SpecificRequest(self):
        print("Adaptee's method called")

# Adapter Class
class Adapter(ITarget):
    def __init__(self):
        self.adaptee = Adaptee()

    def Request(self):
        self.adaptee.SpecificRequest()

# Client Code
if __name__ == '__main__':
    target = Adapter()
    target.Request() # Calls adaptee's method through adapter

15. Provide a scenario where the Command pattern would be preferable to the Strategy pattern.The Command Pattern is preferred when a request needs to be encapsulated as an object so it can be queued, logged, or undone. The Strategy Pattern is used to switch between different algorithms at runtime.Use the Command Pattern for operations like remote controls, undo/redo, task scheduling, or command queues.Use the Strategy Pattern when selecting interchangeable algorithms, such as different payment methods or sorting techniques.16. Explain the Single Responsibility Principle and its significance in Software Design.The Single Responsibility Principle (SRP) states that a class should have only one responsibility and only one reason to change. This makes the code easier to understand, maintain, and modify.Ensures each class focuses on a single task or functionality.Improves code maintainability, readability, and reduces the impact of changes.SignificanceModularity: By implementing SRP the system is more modular and easier to maintain and extend.Maintainability: Changes in one area of the system are less likely to impact other areas that are unrelated, limiting the risk of bugs when changing the code.Readability: Code becomes more readable and easier to comprehend since each class has a defined, singular responsibility.17. What is the Observer Pattern, and how does it allow objects to inform other objects about changes in State?The Observer pattern establishes a one-to-many relationship between objects such that one object (the subject) keeps a list of its dependents (observers) and informs them of changes to the state. The observers are updated automatically whenever the subject's state is changed.Example
            C++

    #include <iostream>
#include <vector>
#include <string>
using namespace std;

// Observer Interface
class Observer {
public:
    virtual void update(const string& message) = 0;
    virtual ~Observer() {}  // Virtual destructor for proper cleanup
};

// Concrete Observer
class ConcreteObserver : public Observer {
private:
    string name;
public:
    ConcreteObserver(const string& observerName) : name(observerName) {}

    void update(const string& message) override {
        cout << name << " received message: " << message << endl;
    }
};

// Subject Class
class Subject {
private:
    vector<Observer*> observers;
public:
    void attach(Observer* observer) {
        observers.push_back(observer);
    }

    void detach(Observer* observer) {
        observers.erase(
            remove(observers.begin(), observers.end(), observer),
            observers.end()
        );
    }

    void notifyObservers(const string& message) {
        for (Observer* observer : observers) {
            observer->update(message);
        }
    }
};

// Client Code
int main() {
    Subject subject;

    ConcreteObserver observer1("Observer 1");
    ConcreteObserver observer2("Observer 2");

    subject.attach(&observer1);
    subject.attach(&observer2);

    subject.notifyObservers("Hello, Observers!");

    subject.detach(&observer1);

    subject.notifyObservers("Second message!");

    return 0;
}


            Java

    import java.util.ArrayList;
import java.util.List;

// Observer Interface
interface Observer {
    void update(String message);
}

// Concrete Observer
class ConcreteObserver implements Observer {
    private String name;

    ConcreteObserver(String observerName) {
        this.name = observerName;
    }

    @Override
    public void update(String message) {
        System.out.println(name + " received message: " + message);
    }
}

// Subject Class
class Subject {
    private List<Observer> observers = new ArrayList<>();

    void attach(Observer observer) {
        observers.add(observer);
    }

    void detach(Observer observer) {
        observers.remove(observer);
    }

    void notifyObservers(String message) {
        for (Observer observer : observers) {
            observer.update(message);
        }
    }
}

// Client Code
public class Main {
    public static void main(String[] args) {
        Subject subject = new Subject();

        ConcreteObserver observer1 = new ConcreteObserver("Observer 1");
        ConcreteObserver observer2 = new ConcreteObserver("Observer 2");

        subject.attach(observer1);
        subject.attach(observer2);

        subject.notifyObservers("Hello, Observers!");

        subject.detach(observer1);

        subject.notifyObservers("Second message!");
    }
}


            Python

    from abc import ABC, abstractmethod
from typing import List

# Observer Interface
class Observer(ABC):
    @abstractmethod
    def update(self, message: str):
        pass

# Concrete Observer
class ConcreteObserver(Observer):
    def __init__(self, observer_name: str):
        self.name = observer_name

    def update(self, message: str):
        print(f"{self.name} received message: {message}")

# Subject Class
class Subject:
    def __init__(self):
        self.observers: List[Observer] = []

    def attach(self, observer: Observer):
        self.observers.append(observer)

    def detach(self, observer: Observer):
        self.observers.remove(observer)

    def notify_observers(self, message: str):
        for observer in self.observers:
            observer.update(message)

# Client Code
if __name__ == "__main__":
    subject = Subject()

    observer1 = ConcreteObserver("Observer 1")
    observer2 = ConcreteObserver("Observer 2")

    subject.attach(observer1)
    subject.attach(observer2)

    subject.notify_observers("Hello, Observers!")

    subject.detach(observer1)

    subject.notify_observers("Second message!")


            JavaScript

    /* Observer Interface */
class Observer {
    update(message) {
        throw new Error('Method update() must be implemented.');
    }
}

/* Concrete Observer */
class ConcreteObserver extends Observer {
    constructor(observerName) {
        super();
        this.name = observerName;
    }

    update(message) {
        console.log(`${this.name} received message: ${message}`);
    }
}

/* Subject Class */
class Subject {
    constructor() {
        this.observers = [];
    }

    attach(observer) {
        this.observers.push(observer);
    }

    detach(observer) {
        this.observers = this.observers.filter(obs => obs!== observer);
    }

    notifyObservers(message) {
        this.observers.forEach(observer => observer.update(message));
    }
}

/* Client Code */
const subject = new Subject();

const observer1 = new ConcreteObserver('Observer 1');
const observer2 = new ConcreteObserver('Observer 2');

subject.attach(observer1);
subject.attach(observer2);

subject.notifyObservers('Hello, Observers!');

subject.detach(observer1);

subject.notifyObservers('Second message!');

18. Define the Open/Closed Principle and how design patterns enforce it.The Open/Closed Principle (OCP) states that software entities should be open for extension but closed for modification. This allows new functionality to be added without changing existing code.Enables new features by extending existing classes instead of modifying them.Design patterns like Strategy, Decorator, and Factory help implement the Open/Closed Principle.Example: Using the Strategy Pattern, new algorithms can be introduced by creating new strategy classes without modifying the existing context code.19. How is the Bridge Pattern different from the Adapter Pattern?The Bridge Pattern separates an abstraction from its implementation so both can evolve independently. The Adapter Pattern converts one interface into another, allowing incompatible classes to work together.Use the Bridge Pattern to decouple an interface from its implementation for greater flexibility.Use the Adapter Pattern to make existing classes with incompatible interfaces work together.Example: Bridge separates a remote control abstraction from device implementations like TV and radio, whereas Adapter allows a legacy device to work with a new control interface.20. In what way does the Dependency Inversion Principle facilitate loose coupling and how does it relate to design patterns?The Dependency Inversion Principle (DIP) states that high-level modules should depend on abstractions, not on concrete implementations. This reduces coupling and makes the system more flexible and maintainable.Promotes loose coupling by relying on interfaces or abstract classes.Design patterns like Factory Method and Dependency Injection help implement the Dependency Inversion Principle.Example: In the Strategy or Factory Pattern, the client depends on an interface, allowing new implementations to be added without modifying existing code.21. Give a real-world example of using the Singleton Pattern in a common library or framework.A common real-world example of the Singleton Pattern is the Runtime class in Java, which ensures that only one instance of the runtime environment exists throughout the application.Provides a single global instance using Runtime.getRuntime().Ensures consistent access to the application's runtime environment.ExampleRuntime runtime = Runtime.getRuntime();This guarantees that the runtime environment is being accessed in a controlled fashion without instantiating multiple objects.22. Give an example where the Strategy pattern is applied to switch between various Algorithms.The Strategy Pattern enables a class to alter its behavior (or algorithm) at runtime. An example would be sorting algorithms. You may employ various sorting strategies based on data size or type.Example
            C++

    #include <iostream>
#include <vector>

class SortingStrategy {
public:
    virtual void sort(std::vector<int>& array) = 0;
};

// Concrete Strategy 1
class BubbleSort : public SortingStrategy {
public:
    void sort(std::vector<int>& array) override {
        std::cout << "BubbleSort selected" << std::endl;
    }
};

// Concrete Strategy 2
class InsertionSort : public SortingStrategy {
public:
    void sort(std::vector<int>& array) override {
        std::cout << "InsertionSort selected" << std::endl;
    }
};

// Context
class SortContext {
private:
    SortingStrategy* strategy;
public:
    SortContext(SortingStrategy* strategy) : strategy(strategy) {}
    void setStrategy(SortingStrategy* strategy) {
        this->strategy = strategy;
    }
    void sort(std::vector<int>& array) {
        strategy->sort(array);
    }
};

// Client
int main() {
    std::vector<int> data = {3, 1, 2};
    SortContext context(new BubbleSort());
    context.sort(data);

    context.setStrategy(new InsertionSort());
    context.sort(data);
    return 0;
}


